using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using LastRail.Battle;
using LastRail.Run;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BRouteNativeTests {
  // Explicit LOCAL route metadata projection around unchanged original v2 fixture source.
  // This is not the actual HTTP run or a server-produced wrapper.
  static BRouteBinding LocalRoute(BBoardingEventsNodeSnapshot source){var p=(JObject)BRouteConsumerTests.Sample()["pendingBinding"].DeepClone();var raw=source.OriginalSource.Capture();var origin=(JObject)raw["origin"];foreach(var key in new[]{"accountId","runId","operationId","selectedRisk"})p[key]=origin[key].DeepClone();p["originalNativeOrigin"]=origin.DeepClone();p["nativeContextId"]=raw["nativeContextId"].DeepClone();p["nativeNodeSource"]=raw.DeepClone();p["pendingNode"]["nodeId"]=raw["nodeId"].DeepClone();p["pendingNode"]["visitDepth"]=raw["visitDepth"].DeepClone();p["pendingNode"]["completedWaveContract"]["nodeId"]=raw["nodeId"].DeepClone();p.Remove("packetHash");p["packetHash"]=BDirectAttackInput.Digest(p).Substring(7);return BRouteBinding.Read(p.ToString(),(string)p["packetHash"],(string)p["accountId"],(string)p["runId"]);}
  // Existing LOCAL fixture has a generic buff context; bind it explicitly to the unchanged node context.
  internal static BDirectAttackBasicLoopBinding Binding(BBoardingEventsNodeSnapshot source){var old=BGunnerInterceptRuntimeTests.Kyle(source);var p=old.Composition.Capture();p["initial"]["contextId"]=source.OriginalSource.NativeContextId;var buff=new BDirectAttackBuffBinding(old.Composition.Attack,old.Composition.Definitions,p,BDirectAttackInput.Digest(p));var r=old.Capture();r["compositionHash"]=buff.OriginalHash;foreach(var row in ((JArray)r["targets"]).Where(x=>(string)x["sourceId"]=="op_kyle").ToArray())row.Remove();return new BDirectAttackBasicLoopBinding(buff,r,BDirectAttackInput.Digest(r));}
  static BTravelRuntimeConfiguration Motion(){var c=global::CombatRailJourneyTests.Config();c["offers"]=new JArray();c["throttleMaximumBps"]=13000;c["throttleCruiseBps"]=10000;return BTravelRuntimeConfiguration.LocalValidation(c,BDirectAttackInput.Digest(c));}
  [Test] public async Task ExistingOriginalNativeGetsManualInputAndExactPauseRestoreThroughRoute(){var source=BBoardingEventsTests.Source(0);var route=LocalRoute(source);var b=Binding(source);var g=BOrdinaryGeometryTests.Geometry(b);var composition=new BRouteNativeComposition(route,source,b,g,Motion(),10000);using(var c=new BRouteSessionController(route.AccountId,route.RunId)){await c.RefreshAsync(()=>Task.FromResult(route));composition.AttachTo(c);int calls=0;c.Bind(_=>calls++);c.Advance("native-route-progress",40000000,1000);Assert.Greater((long)c.Capture()["nodeSession"]["runtime"]["travel"]["motion"]["distanceMm"],0);var state=c.Capture()["nodeSession"]["runtime"];bool attacked=false;foreach(var life in ((JArray)state["boarding"]["lives"]).Where(x=>(bool)x["registered"]&&(bool)x["targetable"]).ToArray()){string id=(string)life["id"];var frame=c.ObserveOrdinaryGeometry("op_kyle",id,(long)state["state"]["direct"]["clock"]["completedSteps"],(long)state["spatialSource"]["revision"],g.Hash);if(!(bool)frame["eligible"])continue;int before=(int)state["state"]["direct"]["enemies"][id]["hp"];c.ApplyWaveBasic("native-route-basic","op_kyle",id,(long)life["generation"]);var after=c.Capture();Assert.Less((int)after["nodeSession"]["runtime"]["state"]["direct"]["enemies"][id]["hp"],before);int once=calls;c.ApplyWaveBasic("native-route-basic","op_kyle",id,(long)life["generation"]);Assert.AreEqual(once,calls);var beforeRejected=c.Capture();Assert.Throws<ArgumentException>(()=>c.ApplyWaveBasic("wrong-life","op_kyle",id,(long)life["generation"]+1));Assert.IsTrue(JToken.DeepEquals(beforeRejected,c.Capture()));Assert.Throws<ArgumentNullException>(()=>c.AcceptInterceptionSource("missing-timing","missing-shot",null));Assert.IsTrue(JToken.DeepEquals(beforeRejected,c.Capture()));attacked=true;break;}Assert.IsTrue(attacked,"Unmodified original stats/geometry must support an eligible manual attack");c.SetPaused("native-route-pause",true);var saved=c.Capture();using(var restored=BRouteSessionController.Restore(saved,BDirectAttackInput.Digest(saved),composition.RestoreNative,route.AccountId,route.RunId)){Assert.IsTrue(JToken.DeepEquals(saved,restored.Capture()));c.SetPaused("native-route-resume",false);restored.SetPaused("native-route-resume",false);c.Advance("native-route-more",1000000,100);restored.Advance("native-route-more",1000000,100);Assert.IsTrue(JToken.DeepEquals(c.Capture(),restored.Capture()));}Assert.IsFalse((bool)c.DescribeRuntimeSources()["acceptedRouteEvidenceSupported"]);File.WriteAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BRouteNative-20261005/local-original-native.json",new JObject{["provenance"]="LOCAL_ROUTE_METADATA_ORIGINAL_V2_SOURCE_UNMODIFIED_KYLE_STATS_MANUAL_INPUT",["route"]=route.Capture(),["boarding"]=source.Capture(),["binding"]=b.Capture(),["geometry"]=g.Capture(),["motion"]=Motion().Capture(),["controller"]=c.Capture(),["observation"]=c.DescribeRuntimeSources(),["nativeWrapperFromActualHttp"]=false,["fullTwoWaveCompletion"]=false,["operatingAcceptedEvidence"]=false}.ToString());}}
  [Test] public void DifferentOriginalNodeAndMissingMotionCannotCompose(){var a=BBoardingEventsTests.Source(0);var other=BBoardingEventsTests.Source(1);var b=Binding(a);var route=LocalRoute(a);var g=BOrdinaryGeometryTests.Geometry(b);Assert.Throws<ArgumentException>(()=>new BRouteNativeComposition(route,other,b,g,Motion(),10000));Assert.Throws<ArgumentException>(()=>new BRouteNativeComposition(route,a,b,g,null,10000));}
  [Test] public async Task InvalidExplicitMotionFactoryDoesNotAttachOrChangeNode(){var source=BBoardingEventsTests.Source(0);var route=LocalRoute(source);var b=Binding(source);var g=BOrdinaryGeometryTests.Geometry(b);var p=Motion().Capture();p.Remove("baseSpeedMillimetersPerSecond");var bad=BTravelRuntimeConfiguration.LocalValidation(p,BDirectAttackInput.Digest(p));var composition=new BRouteNativeComposition(route,source,b,g,bad,10000);using(var c=new BRouteSessionController(route.AccountId,route.RunId)){await c.RefreshAsync(()=>Task.FromResult(route));var before=c.Capture();Assert.Throws<ArgumentException>(()=>composition.AttachTo(c));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));}}
  [Test] public void OriginalTypedNativeCompositionIsRequired(){Assert.NotNull(typeof(BDirectAttackBasicLoop).Assembly.GetType("LastRail.Run.BRouteNativeComposition"));}
  [Test] public void ExistingControllerMustDelegateOriginalBasicAndInterceptionCommands(){Assert.NotNull(typeof(BNodeSessionController).GetMethod("ApplyWaveBasic"));Assert.NotNull(typeof(BRouteSessionController).GetMethod("ApplyWaveBasic"));Assert.NotNull(typeof(BRouteSessionController).GetMethod("AcceptInterceptionSource"));}
 }
